import numpy as np

class Residualizer:
    def __init__(self):
        self.coefficients = None

    def fit(self, X, y):
        # Perform linear regression to obtain coefficients
        self.coefficients = np.linalg.inv(X.T @ X) @ X.T @ y

    def transform(self, X, y):
        if self.coefficients is None:
            raise ValueError("Residualizer has not been fitted yet")
        else:
            y_hat = X @ self.coefficients
            residuals = y - y_hat
            return residuals

class ResidualizerEstimator:
    def __init__(self):
        self.coefficients = None

    def fit(self, X, y):
        # Perform linear regression to obtain coefficients
        self.coefficients = np.linalg.inv(X.T @ X) @ X.T @ y

    def predict(self, X):
        if self.coefficients is None:
            raise ValueError("ResidualizerEstimator has not been fitted yet")
        else:
            return X @ self.coefficients

# __init__.py
__all__ = ['Residualizer', 'ResidualizerEstimator']
```

