    base = pd.to_datetime(base_date)
    result_dates = []
    for offset, offset_type in offsets:
        if offset_type == 'B':
            result_dates.append((base + pd.offsets.BDay(offset)).strftime('%Y-%m-%d'))
        elif offset_type == 'W':
            result_dates.append((base + pd.offsets.Week(offset)).strftime('%Y-%m-%d'))
        elif offset_type == 'M':
            result_dates.append((base + pd.offsets.MonthBegin(offset)).strftime('%Y-%m-%d'))
        elif offset_type == 'Q':
            result_dates.append((base + pd.offsets.QuarterBegin(offset)).strftime('%Y-%m-%d'))
        elif offset_type == 'H':
            result_dates.append((base + pd.offsets.Hour(offset)).strftime('%Y-%m-%d'))
        elif offset_type == 'T':
            result_dates.append((base + pd.offsets.Minute(offset)).strftime('%Y-%m-%d'))
        else:
