class MLP(nn.Module):
    def __init__(self, features_dim, action_dim, net_arch, activation_fn, squash_output=True):
        super(MLP, self).__init__()
        layers = []
        input_dim = features_dim
        for layer_size in net_arch:
            layers.append(nn.Linear(input_dim, layer_size))
            layers.append(get_activation_fn(activation_fn))
            input_dim = layer_size
        layers.append(nn.Linear(input_dim, action_dim))
        if squash_output:
            layers.append(nn.Tanh())  # Squash output to [-1, 1] range
        self.model = nn.Sequential(*layers)

    def forward(self, x):
        return self.model(x)

def get_activation_fn(activation_fn):
    if activation_fn == 'relu':
        return nn.ReLU()
    elif activation_fn == 'tanh':
        return nn.Tanh()
    elif activation_fn == 'sigmoid':
        return nn.Sigmoid()
    else:
        raise ValueError(f"Activation function '{activation_fn}' not supported")

def create_mlp(features_dim, action_dim, net_arch, activation_fn, squash_output=True):
    return MLP(features_dim, action_dim, net_arch, activation_fn, squash_output)
