import numpy

def golden_section_search(func, bracket, maxiter=100, tol=1e-6):
    xa, xb, xc = bracket
    _verysmall_num = 1e-21  # Small number to avoid division by zero
    grow_limit = 2.0  # Limit for interval growth

    def evaluate_function(x):
        return func(*((x,) + args))

    args = ()  # Additional arguments for the objective function

    iter = 0
    while iter < maxiter:
        fa = evaluate_function(xa)
        fb = evaluate_function(xb)
        fc = evaluate_function(xc)

        tmp1 = (xb - xa) * (fb - fc)
        tmp2 = (xb - xc) * (fb - fa)
        val = tmp2 - tmp1

        if numpy.abs(val) < _verysmall_num:
            denom = 2.0 * _verysmall_num
        else:
            denom = 2.0 * val

        w = numpy.clip(xb - ((xb - xc) * tmp2 - (xb - xa) * tmp1) / denom, bounds[0], bounds[1])
        wlim = xb + grow_limit * (xc - xb)

        if (w - xb) * (w - xc) > 0:
            fw = evaluate_function(w)
            if fw < fc:
                xa, xb, xc = xb, w, xc
            elif fw > fb:
                xa, xb, xc = xa, w, xb
            else:
                xa, xb, xc = xa, w, xc
                fb = fw
        else:
            if (w - wlim) * (wlim - xb) >= 0:
                fw = evaluate_function(w)
                if fw < fc:
                    xa, xb, xc = xb, w, xc
                else:
                    xa, xb, xc = xa, w, xc
                    fb = fw
            elif (w - wlim) * (wlim - xb) < 0:
                fw = evaluate_function(wlim)
                if fw < fc:
                    xa, xb, xc = xb, wlim, xc
                elif fw > fb:
                    xa, xb, xc = xa, wlim, xb
                else:
                    xa, xb, xc = xa, wlim, xc
                    fb = fw

        iter += 1

        if numpy.abs(xc - xa) < tol:
            return (xa + xc) / 2.0

    return (xa + xc) / 2.0  # Return the optimized solution if convergence criterion not met
```

This solution provides a complete implementation of the golden section search algorithm for optimizing a given objective function within a specified bracketing interval. The algorithm iteratively updates the interval and function evaluations until the convergence criterion is met or the maximum number of iterations is reached. The function handles cases where the convergence criterion is not met within the specified maximum number of iterations.

