import numpy as np

class PowerBijector(tfp.bijectors.Bijector):
    def __init__(self, power, validate_args=False):
        self._power = power
        super(PowerBijector, self).__init__(
            validate_args=validate_args,
            forward_min_event_ndims=0,
            inverse_min_event_ndims=0)

    @property
    def power(self):
        return self._power

    def _forward(self, x):
        return tf.sign(x) * tf.abs(x) ** self._power

    def _inverse(self, y):
        return tf.sign(y) * tf.abs(y) ** (1.0 / self._power)

    def _forward_log_det_jacobian(self, x):
        return tf.math.log(tf.abs(self._power * tf.abs(x) ** (self._power - 1.0)))

    def _inverse_log_det_jacobian(self, y):
        return tf.math.log(tf.abs(1.0 / self._power * tf.abs(y) ** (1.0 / self._power - 1.0)))

